bounded_host_request.command:
set -eu
test "$(docker inspect deploy-gaybbs-1 --format '{{.State.Running}}')" = true
test "$(docker inspect deploy-gaybbs-1 --format '{{.RestartCount}}')" = 0
test "$(docker inspect deploy-gaybbs-1 --format '{{.Image}}')" = "$(docker image inspect gace-tgtumbler-gaybbs:profile-candidate --format '{{.Id}}')"
docker exec deploy-gaybbs-1 node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module -e '
import {readFileSync} from "node:fs";
const t=readFileSync("/run/secrets/bot_token","utf8").trim();
const r=await fetch("https://api.telegram.org/bot"+t+"/getMe",{signal:AbortSignal.timeout(15000)});
const d=await r.json();
if(!d.ok||typeof d.result?.username!=="string"||!d.result.username.toLowerCase().includes("gaybbs"))process.exit(2);
'
printf 'PROFILE_RUNTIME_TELEGRAM_AUTH=PASS\n'
